  const lead = $('Standardize Lead Fields').first().json;

// text ko saaf karo taake capital/space ka farq masla na banay
const norm = (s) => String(s ?? '').trim().toLowerCase();

const budgetPoints = {
  'under $500': 0,
  '$500': 0,
  '$500-$999': 1,
  '$1,000-$2,499': 3,
  '$2,500+': 5
};

const timelinePoints = {
  'just exploring': 0,
  '1-3 months': 1,
  'within 1 month': 2,
  'within 2 weeks': 3,
  'asap': 4
};

const servicePoints = {
  'other': 0,
  'seo': 1,
  'digital marketing': 1,
  'website development': 2,
  'e-commerce website': 2
};

const warnings = [];

function pointsFor(map, value, fieldName) {
  const key = norm(value);
  if (key in map) return map[key];
  warnings.push(`${fieldName} not matched: "${value}"`);
  return 0;
}

let score = 0;
score += pointsFor(budgetPoints, lead.budget, 'budget');
score += pointsFor(timelinePoints, lead.timeline, 'timeline');
score += pointsFor(servicePoints, lead.service, 'service');
if ((lead.project_description || '').length > 20) score += 1;

let temperature = 'Not Fit';
if (score >= 8) temperature = 'Hot';
else if (score >= 4) temperature = 'Warm';

return [{
  json: {
    ...lead,
    lead_score: score,
    lead_temperature: temperature,
    scoring_warning: warnings.join(' | ')
  }
}];
